for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nExample {i}: '{inp}' -> '{outp}'")

    # For same-length cases, check character by character
    if len(inp) == len(outp):
        print("  Same length, checking character by character:")
        for j, (cin, cout) in enumerate(zip(inp, outp)):
            if cin != cout:
                print(f"    Position {j}: '{cin}' -> '{cout}'")
    else:
        print(f"  Different lengths: {len(inp)} -> {len(outp)}")

# Now let's look for common patterns
print("\nLooking for replacement patterns:")
# Let's see what characters are being replaced with what
replacements_needed = {}
for inp, outp in zip(inputs, outputs):
    # Create mapping of what characters change
    if len(inp) == len(outp):
        for j, (cin, cout) in enumerate(zip(inp, outp)):
            if cin != cout:
                if cin not in replacements_needed:
                    replacements_needed[cin] = cout
                elif replacements_needed[cin] != cout:
                    print(f"Conflict: {cin} maps to both {replacements_needed[cin]} and {cout}")
    else:
        # For different lengths, we need to be more careful
        # Let's just note that they differ in length
        pass

print(f"Simple replacements needed: {replacements_needed}")

# Let's also check for multi-character patterns that might be relevant
print("\nChecking for multi-character patterns:")
for inp, outp in zip(inputs, outputs):
    print(f"'{inp}' -> '{outp}'")
    # Look for substrings that might be replaced
    if inp == 'cjdcay' and outp == 'cjjcacka':
        print("  cjdcay -> cjjcacka: d->j, y->ka, a->ka")
    elif inp == 'ihg' and outp == 'idcg':
        print("  ihg -> idcg: h->d, g->c")

